// SIR STICKS — a stick figure with one sword and a lot of confidence about it.
//   STRIKE   the sword swings: forward slash, overhead arc, downward stab; charged for the smash.
//   GIMMICK  SWORD THROW: hurl it, it sticks where it lands; walk over it to pull it back out.
//   RECOVERY the sword points up and he corkscrews skyward.
//   GRAB     the empty arm hooks them; hilt bonk and a shove.
// Swordless, every strike hits for less but comes out faster (the blade hitboxes stay, the damage drops).
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops } = api;

  const stats = {
    weight: 82, walk: 3.4, run: 6.0, dashInit: 6.8, airSpeed: 4.4, airAccel: 0.22,
    fallSpeed: 6.8, fastFall: 10.5, gravity: 0.42, shortHop: 8, fullHop: 13, doubleJump: 12,
    jumps: 2, wallJump: false, traction: 0.55, height: 104, width: 36, crouchHeight: 72, landLag: 4, ledgeReach: 38,
  };

  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.96, sy: 1.04, ...extra })),
    key(hit, P({ rot: lean, sx: 1.1, sy: 0.94, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.04, sy: 0.98, ...extra })),
    key(total, rest),
  ];
  const BLADE = { fx: 'slash' };

  // THE STRIKE: the drawn blade. atk-fwd blade runs (27,-47)->(66,-50); atk-up (12,-89)->(-5,-115); atk-down (10,-27)->(43,-2).
  const STRIKE = { total: 30, hit: 8, active: 4, damage: 11, r: 10 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === 'u' ? [12, -86] : dir === 'b' ? [-18, -47] : dir === 'd' ? [10, -27] : [18, -47];
    const end = dir === 'u' ? [-4, -114] : dir === 'b' ? [-64, -50] : dir === 'd' ? [43, -4] : [64, -50];
    const angle = dir === 'u' ? 86 : dir === 'd' ? 30 : 40;
    const lean = dir === 'u' ? -8 : dir === 'b' ? -16 : dir === 'd' ? 8 : 14;
    const extra = dir === 'd' ? { sy: 0.9, dy: 4 } : dir === 'u' ? { dy: -4 } : {};
    const cell = dir === 'u' ? 'atk-up' : dir === 'd' ? 'atk-down' : 'atk-fwd';
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 38, s.growth ?? 84, { ...BLADE, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === 'b', hook: 'blade', ...(s.mv ?? {}) });
  };
  const GRAB = { total: 34, hit: 7, damage: 8 };
  const toss = (id, angle, base, growth, pose) => throwMove(id, 30, 13, GRAB.damage, angle, base, growth, [key(0, P({ rot: 6 })), key(13, P(pose)), key(30, rest)]);

  const moves = {
    jab1: aim('jab1', 'f', { total: 22, hit: 5, damage: 6, mv: { iasa: 16 } }),
    ftilt: aim('ftilt', 'f'),
    dashAttack: aim('dashAttack', 'f', { total: 36, hit: 9, damage: 10, mv: { motion: [[1, 7, 0], [12, 4, 0], [20, 1, 0]] } }),
    nair: aim('nair', 'f', { total: 28, hit: 7, damage: 8, mv: { aerial: true, landingLag: 9 } }),
    fair: aim('fair', 'f', { mv: { aerial: true, landingLag: 11 } }),
    bair: aim('bair', 'b', { damage: 12, mv: { aerial: true, landingLag: 11, cell: 'atk-fwd' } }),
    utilt: aim('utilt', 'u', { damage: 10 }),
    uair: aim('uair', 'u', { damage: 10, mv: { aerial: true, landingLag: 9 } }),
    dtilt: aim('dtilt', 'd', { damage: 9 }),
    dair: aim('dair', 'd', { total: 38, hit: 12, damage: 12, hb: { spike: true }, mv: { aerial: true, landingLag: 15 } }),
    // charged: big two-beat wind-up, full-body swing with a sweetspot at the tip
    fsmash: mv('fsmash', 50, [
      cap([16, 19], 44, -50, 70, -50, 12, 19, 38, 44, 100, { fx: 'tip', priority: 0 }),
      cap([16, 20], 4, -46, 46, -50, 12, 15, 40, 40, 84, { ...BLADE, priority: 1 }),
    ], [key(0, P({ rot: -6, sx: 0.96 })), key(7, P({ rot: -14, sx: 0.92, sy: 1.06 })), key(10, P({ rot: -8 })), key(15, P({ rot: -18, sx: 0.9, sy: 1.08 })), key(16, P({ rot: 22, sx: 1.16, sy: 0.92 })), key(24, P({ rot: 16, sx: 1.06 })), key(50, rest)], { smash: true, cell: 'atk-fwd', hook: 'blade' }),
    usmash: aim('usmash', 'u', { total: 48, hit: 14, active: 6, damage: 16, r: 13, base: 42, growth: 98, mv: { smash: true } }),
    dsmash: mv('dsmash', 52, [
      cap([15, 18], 10, -27, 46, -3, 13, 15, 30, 44, 88, { ...BLADE, group: 0 }),
      cap([22, 25], -10, -27, -46, -3, 13, 15, 30, 44, 88, { ...BLADE, group: 1 }),
    ], [key(0, P({ sy: 0.92 })), key(15, P({ rot: 12, sx: 1.12, sy: 0.86 })), key(22, P({ rot: -12, sx: 1.12, sy: 0.86 })), key(52, rest)], { smash: true, cell: 'atk-down', hook: 'blade' }),
    // grab: the empty arm hooks
    grab: mv('grab', GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 30, -50, 18, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 10), { isGrab: true }),
    dashGrab: mv('dashGrab', 40, [hb([9, 11], 40, -50, 20, 0, 0, 0, 0, { grab: true })], strikePoses(40, 9, 18), { isGrab: true, motion: [[1, 5, 0], [9, 0, 0]] }),
    pummel: mv('pummel', 16, [], [key(0, P({ rot: 4 })), key(6, P({ rot: 14, dy: 3 })), key(16, P({ rot: 4 }))]),
    fthrow: toss('fthrow', 42, 58, 72, { rot: 22, sx: 1.1 }),
    bthrow: toss('bthrow', 40, 62, 78, { rot: -34 }),
    uthrow: toss('uthrow', 90, 66, 88, { dy: -10, sy: 1.12 }),
    dthrow: toss('dthrow', 70, 44, 42, { sy: 0.82, sx: 1.12, dy: 10 }),
    // GIMMICK, SWORD THROW
    nspecial: mv('nspecial', 40, [], [key(0, P({ rot: -14, sx: 0.94 })), key(10, P({ rot: 20, sx: 1.12, sy: 0.94 })), key(18, P({ rot: 14 })), key(40, rest)], { hook: 'hurl', cell: 'atk-fwd' }),
    sspecial: mv('sspecial', 40, [], [key(0, P({ rot: -14, sx: 0.94 })), key(10, P({ rot: 20, sx: 1.12, sy: 0.94 })), key(18, P({ rot: 14 })), key(40, rest)], { hook: 'hurl', cell: 'atk-fwd' }),
    // held down: stab it into the ground at his feet as a hazard
    dspecial: mv('dspecial', 36, [cap([12, 14], 10, -27, 43, -4, 11, 9, 70, 40, 60, BLADE)], [key(0, P({ sy: 1.04 })), key(12, P({ sy: 0.84, sx: 1.1, dy: 4 })), key(22, P({ sy: 0.9 })), key(36, rest)], { hook: 'plant', cell: 'atk-down' }),
    // RECOVERY, CORKSCREW: blade up, spinning skyward, steerable
    uspecial: mv('uspecial', 52, [cap([5, 22], 0, -40, 0, -118, 16, 3, 88, 30, 40, { ...BLADE, rehit: 5 }), cap([23, 25], 0, -40, 0, -118, 18, 6, 80, 50, 90, { fx: 'heavy', group: 1 })], [key(0, P({ sy: 0.86, sx: 1.1 })), key(5, P({ sy: 1.14, sx: 0.9, rot: 30 })), key(12, P({ rot: -30, sy: 1.1 })), key(19, P({ rot: 30, sy: 1.1 })), key(26, P({ rot: 0 })), key(52, P({ rot: -8 }))], { hook: 'corkscrew', helpless: true, ledgeOk: true, cell: 'jump' }),
    ledgeAttack: aim('ledgeAttack', 'f', { total: 38, hit: 11, damage: 8 }),
    getupAttack: mv('getupAttack', 42, [cap([11, 14], 10, -40, 64, -44, 11, 7, 45, 40, 60, { ...BLADE, group: 0 }), cap([19, 22], -10, -40, -64, -44, 11, 7, 45, 40, 60, { ...BLADE, group: 1 })], [key(0, rest), key(11, P({ rot: 14 })), key(19, P({ rot: -14 })), key(42, rest)]),
    taunt: mv('taunt', 50, [], [key(0, rest), key(12, P({ rot: -10, sy: 1.08, dy: -4 })), key(26, P({ rot: 8, sy: 1.1 })), key(50, rest)], { cell: 'atk-up' }),
  };

  // sword: 1 in hand, 0 away. flying: 1 in the air, 0 planted. groundY: last floor height he stood on.
  const pullOut = (f) => { f.special.sword = 1; f.special.flying = 0; f.special.flyT = 0; };

  return {
    id: 'sirsticks',
    name: 'SIR STICKS',
    tagline: 'Has one sword and a lot of confidence about it.',
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: '#d23a32' }, accent: 'marker', outline: '#1d1d1b' },
    special: () => ({ sword: 1, sx: 0, sy: 0, svx: 0, svy: 0, flying: 0, flyT: 0, groundY: 0, hazardCd: 0 }),
    hooks: {
      // swordless: a fast, pathetic stick-arm slap
      blade: ({ f }) => {
        if (f.special.sword) return;
        if (f.frame === 1) f.chargeMul = 0.4;
        if (f.frame > 1 && f.frame < 6 && (f.frame & 1) === 0) f.frame++;
      },
      hurl: ({ state, f }) => {
        if (f.frame !== 10 || !f.special.sword) return;
        const s = f.special;
        s.sword = 0; s.flying = 1; s.flyT = 0;
        s.sx = f.x + f.moveFacing * 30; s.sy = f.y - 50;
        s.svx = f.moveFacing * 15; s.svy = -1;
        spawnProjectile(state, f, 'sword', s.sx, s.sy, s.svx, s.svy, 18,
          { frames: [0, 999], x: 0, y: 0, r: 12, damage: 10, angle: 36, base: 40, growth: 70, fx: 'slash' }, { g: 0.3 });
      },
      plant: ({ f }) => {
        if (f.frame !== 12 || !f.special.sword) return;
        const s = f.special;
        s.sword = 0; s.sx = f.x + f.moveFacing * 30; s.svx = 0; s.flyT = 0;
        if (f.grounded) { s.flying = 0; s.sy = f.y; s.svy = 0; } else { s.flying = 1; s.sy = f.y; s.svy = 8; }
      },
      corkscrew: ({ f, input }) => {
        const armed = f.special.sword === 1;
        if (f.frame === 5) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        const end = armed ? 30 : 18;
        if (f.frame >= 5 && f.frame <= end) {
          f.vy = (armed ? -9.5 : -8) + (f.frame - 5) * 0.2;
          f.vx = (input.x / 100) * (armed ? 5 : 4);
        }
      },
    },
    onFrame: ({ state, f }) => {
      const s = f.special;
      if (f.grounded) s.groundY = f.y;
      if (s.hazardCd > 0) s.hazardCd--;
      if (s.sword) return;
      if (s.flying) {
        s.flyT++;
        s.svy = Math.min(14, s.svy + 0.3);
        if (s.flyT > 18) s.svx *= 0.9;
        s.sx += s.svx; s.sy += s.svy;
        // sticks point-first when it reaches floor height; lost off-stage, it pops back into his hand
        if (s.sy >= s.groundY && s.svy > 0) { s.sy = s.groundY; s.flying = 0; s.svx = 0; s.svy = 0; }
        else if (s.sy > s.groundY + 600) pullOut(f);
        return;
      }
      if (f.grounded && Math.abs(f.x - s.sx) < 22 && Math.abs(f.y - s.sy) < 30) { pullOut(f); return; }
      // planted: anyone knocked into it at speed gets cut
      if (s.hazardCd > 0 || !state || !state.fighters) return;
      for (const o of state.fighters) {
        if (o === f) continue;
        const dx = o.x - s.sx, dy = (o.y - 40) - (s.sy - 20);
        const sp = o.vx * o.vx + o.vy * o.vy;
        if (sp > 36 && dx * dx + dy * dy < 40 * 40) {
          spawnProjectile(state, f, 'swordHazard', s.sx, s.sy - 20, 0, 0, 3,
            { frames: [0, 999], x: 0, y: 0, r: 26, damage: 8, angle: 80, base: 45, growth: 60, fx: 'slash' }, { g: 0 });
          s.hazardCd = 40;
          break;
        }
      }
    },
    meters: [{ label: 'SWORD', color: '#d23a32', get: (f) => f.special.sword }],
    visual: (f) => ({ glow: 0 }),
  };
}
